/**
 * Fails when a file is larger than the limit, so a stray video, export or build
 * artifact does not land in Git history.
 * Run: node scripts/check-file-size.ts [files...]   (no files: every tracked file)
 */
import { execFileSync } from 'node:child_process';
import { existsSync, statSync } from 'node:fs';

const LIMIT_BYTES = 1024 * 1024;
// Files that are allowed to be large, with the reason.
const ALLOWED = new Set([
  'package-lock.json', // generated by npm
]);

const args = process.argv.slice(2);
const files = args.length
  ? args
  : execFileSync('git', ['ls-files'], { encoding: 'utf8' }).split('\n').filter(Boolean);

const tooLarge = files
  .filter((file) => existsSync(file) && !ALLOWED.has(file))
  .map((file) => ({ file, size: statSync(file).size }))
  .filter(({ size }) => size > LIMIT_BYTES);

for (const { file, size } of tooLarge) {
  console.error(`${file} is ${(size / 1024 / 1024).toFixed(1)} MB, over the 1 MB limit.`);
}
if (tooLarge.length) {
  console.error(
    'Compress the file, or add it to ALLOWED in scripts/check-file-size.ts with a reason.',
  );
  process.exit(1);
}
console.log(`file size: ${files.length} files under 1 MB`);
